import{_ as a,o,c as r,a2 as l}from"./chunks/framework.BXzK3EA4.js";const f=JSON.parse('{"title":"Referencia: Clase RestProcessor 🏛️","description":"","frontmatter":{},"headers":[],"relativePath":"api/processor.md","filePath":"api/processor.md","lastUpdated":null}'),s={name:"api/processor.md"};function t(i,e,n,c,d,u){return o(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="referencia-clase-restprocessor-🏛️" tabindex="-1">Referencia: Clase <code>RestProcessor</code> 🏛️ <a class="header-anchor" href="#referencia-clase-restprocessor-🏛️" aria-label="Permalink to &quot;Referencia: Clase `RestProcessor` 🏛️&quot;">​</a></h1><p>Clase principal que actúa como Fluent Builder para orquestar la cadena de procesamiento de consultas REST en Laravel.</p><p>Namespace: <code>Warrior\\RestProcessor\\RestProcessor</code></p><hr><h2 id="🏗️-metodos-de-inicializacion" tabindex="-1">🏗️ Métodos de Inicialización <a class="header-anchor" href="#🏗️-metodos-de-inicializacion" aria-label="Permalink to &quot;🏗️ Métodos de Inicialización&quot;">​</a></h2><h3 id="restprocessor-for-subject-request-request-null-self" tabindex="-1"><code>RestProcessor::for($subject, ?Request $request = null): self</code> <a class="header-anchor" href="#restprocessor-for-subject-request-request-null-self" aria-label="Permalink to &quot;`RestProcessor::for($subject, ?Request $request = null): self`&quot;">​</a></h3><p>Punto de entrada principal para crear una nueva instancia del procesador.</p><ul><li><strong>Parámetros:</strong><ul><li><code>$subject</code>: Puede ser un <code>class-string&lt;Model&gt;</code> (ej: <code>User::class</code>), una instancia de <code>Builder</code> (ej: <code>User::where(&#39;active&#39;, true)</code>), o una instancia de <code>Relation</code> (ej: <code>$user-&gt;posts()</code>).</li><li><code>$request</code>: Objeto <code>Illuminate\\Http\\Request</code> opcional. Si se omite, se resuelve automáticamente con el helper <code>request()</code>.</li></ul></li><li><strong>Retorno:</strong> Instancia de <code>RestProcessor</code>.</li></ul><hr><h2 id="🔧-metodos-de-configuracion-encadenables" tabindex="-1">🔧 Métodos de Configuración (Encadenables) <a class="header-anchor" href="#🔧-metodos-de-configuracion-encadenables" aria-label="Permalink to &quot;🔧 Métodos de Configuración (Encadenables)&quot;">​</a></h2><h3 id="allowedfilters-array-filters-self" tabindex="-1"><code>allowedFilters(array $filters): self</code> <a class="header-anchor" href="#allowedfilters-array-filters-self" aria-label="Permalink to &quot;`allowedFilters(array $filters): self`&quot;">​</a></h3><p>Define la lista blanca de filtros autorizados para la petición.</p><ul><li>Acepta nombres de columnas directas (<code>&#39;name&#39;</code>), relaciones (<code>&#39;roles.name&#39;</code>), comodines (<code>&#39;*&#39;</code>, <code>&#39;roles.*&#39;</code>), campos JSON (<code>&#39;extra_data.client.code&#39;</code>), nombres de Local Scopes (<code>&#39;active&#39;</code>) o instancias de <code>CustomFilter</code> creadas con <code>Filter::custom()</code>.</li></ul><h3 id="defaultfilters-array-defaults-self" tabindex="-1"><code>defaultFilters(array $defaults): self</code> <a class="header-anchor" href="#defaultfilters-array-defaults-self" aria-label="Permalink to &quot;`defaultFilters(array $defaults): self`&quot;">​</a></h3><p>Define valores por defecto a nivel de petición HTTP si el cliente omite el parámetro.</p><ul><li>Mantiene la consulta base inmutable y permite que el cliente sobrescriba el valor.</li></ul><h3 id="allowedincludes-array-includes-self" tabindex="-1"><code>allowedIncludes(array $includes): self</code> <a class="header-anchor" href="#allowedincludes-array-includes-self" aria-label="Permalink to &quot;`allowedIncludes(array $includes): self`&quot;">​</a></h3><p>Define las relaciones de Eloquent autorizadas para carga anticipada (<em>Eager Loading</em>) mediante <code>with()</code>. Previene el problema de $N+1$ queries.</p><h3 id="allowedcounts-array-counts-self" tabindex="-1"><code>allowedCounts(array $counts): self</code> <a class="header-anchor" href="#allowedcounts-array-counts-self" aria-label="Permalink to &quot;`allowedCounts(array $counts): self`&quot;">​</a></h3><p>Define las relaciones autorizadas para conteos agregados virtuales mediante <code>withCount()</code>.</p><h3 id="allowedsearch-array-columns-self" tabindex="-1"><code>allowedSearch(array $columns): self</code> <a class="header-anchor" href="#allowedsearch-array-columns-self" aria-label="Permalink to &quot;`allowedSearch(array $columns): self`&quot;">​</a></h3><p>Define el listado de columnas de texto (directas o relacionales) sobre las cuales actuará el parámetro global <code>?search=</code>.</p><h3 id="allowedsorts-array-sorts-self" tabindex="-1"><code>allowedSorts(array $sorts): self</code> <a class="header-anchor" href="#allowedsorts-array-sorts-self" aria-label="Permalink to &quot;`allowedSorts(array $sorts): self`&quot;">​</a></h3><p>Define las columnas de la tabla base autorizadas para ser ordenadas mediante <code>?sort=</code>.</p><h3 id="defaultsort-string-column-string-direction-asc-self" tabindex="-1"><code>defaultSort(string $column, string $direction = &#39;asc&#39;): self</code> <a class="header-anchor" href="#defaultsort-string-column-string-direction-asc-self" aria-label="Permalink to &quot;`defaultSort(string $column, string $direction = &#39;asc&#39;): self`&quot;">​</a></h3><p>Sobrescribe la columna y dirección de ordenamiento por defecto cuando el cliente no especifica el parámetro <code>sort</code>.</p><ul><li>Si la columna se pasa con prefijo <code>-</code> (ej: <code>&#39;-created_at&#39;</code>), se infiere automáticamente orden descendente.</li></ul><h3 id="allowall-int-bool-maxlimitorunlimited-5000-self" tabindex="-1"><code>allowAll(int|bool $maxLimitOrUnlimited = 5000): self</code> <a class="header-anchor" href="#allowall-int-bool-maxlimitorunlimited-5000-self" aria-label="Permalink to &quot;`allowAll(int|bool $maxLimitOrUnlimited = 5000): self`&quot;">​</a></h3><p>Habilita explícitamente el flag <code>?all=true</code> para recuperar todos los registros sin paginar en formato de array plano.</p><ul><li><code>$maxLimitOrUnlimited</code>: Límite máximo de registros permitidos (entero) o <code>true</code> para ilimitado.</li></ul><hr><h2 id="🏁-metodos-terminales-resolucion" tabindex="-1">🏁 Métodos Terminales (Resolución) <a class="header-anchor" href="#🏁-metodos-terminales-resolucion" aria-label="Permalink to &quot;🏁 Métodos Terminales (Resolución)&quot;">​</a></h2><h3 id="response-string-resourceclass-null-jsonresponse" tabindex="-1"><code>response(?string $resourceClass = null): JsonResponse</code> <a class="header-anchor" href="#response-string-resourceclass-null-jsonresponse" aria-label="Permalink to &quot;`response(?string $resourceClass = null): JsonResponse`&quot;">​</a></h3><p>Ejecuta la pipeline completa y retorna una respuesta JSON (<code>Illuminate\\Http\\JsonResponse</code>) lista para retornar en el controlador:</p><ul><li>Si se solicitó <code>?all=true</code>, devuelve directamente un <strong>array plano</strong> <code>[ {...}, {...} ]</code>.</li><li>Si se pasó <code>$resourceClass</code> (ej: <code>UserResource::class</code>), envuelve los datos con la colección del Resource.</li><li>Si es paginación normal sin resource, devuelve el objeto paginador estándar de Laravel.</li></ul><h3 id="get-lengthawarepaginator-paginator-cursorpaginator-collection" tabindex="-1"><code>get(): LengthAwarePaginator|Paginator|CursorPaginator|Collection</code> <a class="header-anchor" href="#get-lengthawarepaginator-paginator-cursorpaginator-collection" aria-label="Permalink to &quot;`get(): LengthAwarePaginator|Paginator|CursorPaginator|Collection`&quot;">​</a></h3><p>Ejecuta la pipeline completa y retorna el resultado nativo de Laravel (<code>Collection</code> si vino <code>all=true</code>, o la instancia de <code>Paginator</code> correspondiente).</p><h3 id="paginate-int-perpage-null-lengthawarepaginator-paginator-cursorpaginator-collection" tabindex="-1"><code>paginate(?int $perPage = null): LengthAwarePaginator|Paginator|CursorPaginator|Collection</code> <a class="header-anchor" href="#paginate-int-perpage-null-lengthawarepaginator-paginator-cursorpaginator-collection" aria-label="Permalink to &quot;`paginate(?int $perPage = null): LengthAwarePaginator|Paginator|CursorPaginator|Collection`&quot;">​</a></h3><p>Alias semántico de <code>get()</code> enfocado en paginación estándar, permitiendo sobrescribir <code>$perPage</code> de forma directa en el código.</p>',39)])])}const m=a(s,[["render",t]]);export{f as __pageData,m as default};
